(()=>{let topic='All';const search=document.querySelector('#insight-search'),cards=[...document.querySelectorAll('.insight-card')];function filter(){const q=search.value.trim().toLowerCase();let count=0;for(const card of cards){const show=(topic==='All'||card.dataset.topic===topic)&&card.textContent.toLowerCase().includes(q);card.hidden=!show;if(show)count++}document.querySelector('#insight-count').textContent=count+' '+(count===1?'guide':'guides');document.querySelector('#insight-empty').hidden=count!==0}document.querySelectorAll('[data-topic-filter]').forEach(b=>b.onclick=()=>{topic=b.dataset.topicFilter;document.querySelectorAll('[data-topic-filter]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));filter()});search.addEventListener('input',filter)})();
